record=dict(status='passed_static_only',abstract_word_count=len(words),reference_entries=len(keys),all_cited=True,undefined_labels=[],duplicate_labels=[],source_sha256={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in texts},not_final=True,warning='Static checks only; native3seed and independentanalysis complete; finalrender and humanauthorapproval require separate checks.')
